reference_solution:
nums = [int(x) for x in input().split()]

squares = [x * x for x in nums if x % 2 != 0]

if squares:
    print(" ".join(str(x) for x in squares))
else:
    print("NONE")

words = input().split(",")

clean = {w.strip().lower() for w in words if w.strip()}

if clean:
    for word in sorted(clean):
        print(word)
else:
    print("NONE")

s = input()

indices = {ch: [i for i, c in enumerate(s) if c == ch] for ch in s}

print(indices)

n = int(input())

d = {}
for _ in range(n):
    key, value = input().split()
    d[key] = int(value)

min_v = int(input())

filtered = {k: v for k, v in d.items() if v > min_v}

print(filtered)

xs = [int(x) for x in input().split()]
ys = [int(y) for y in input().split()]
t = int(input())

pairs = [(x, y) for x in xs for y in ys if x + y == t]

if pairs:
    for pair in pairs:
        print(pair)
else:
    print("NONE")

import json

data = json.loads(input())

honor = [
    (cls["name"], st["name"], round(sum(st["grades"]) / len(st["grades"]), 1))
    for cls in data["classes"]
    for st in cls["students"]
    if st["grades"] and sum(st["grades"]) / len(st["grades"]) >= 90
]

if honor:
    for class_name, name, avg in honor:
        print(class_name, name, avg)
else:
    print("NONE")
